// Read the incoming Telegram message safely
const msg = $input.first().json.message || {};
const text = String(msg.text || '').trim();
const chatId = msg.chat ? msg.chat.id : null;

// Expect exactly: /ip <something>  (also allows /ip@YourBot)
const match = text.match(/^\/ip(?:@\w+)?\s+(\S+)$/i);

let valid = false;
let ip = '';
let error = '';

if (!match) {
  error = 'Usage: /ip <IPv4 address>, for example /ip 1.1.1.1';
} else {
  ip = match[1];
  // Strict IPv4: four numbers from 0 to 255, no leading zeros
  const ipv4 = /^(?:(?:25[0-5]|2[0-4]\d|1\d\d|[1-9]?\d)\.){3}(?:25[0-5]|2[0-4]\d|1\d\d|[1-9]?\d)$/;
  if (!ipv4.test(ip)) {
    error = 'That is not a valid IPv4 address. Example: /ip 1.1.1.1';
  } else {
    const [a, b] = ip.split('.').map(Number);
    const isPrivate =
      a === 0 || a === 10 || a === 127 || a >= 224 ||
      (a === 169 && b === 254) ||
      (a === 172 && b >= 16 && b <= 31) ||
      (a === 192 && b === 168) ||
      (a === 100 && b >= 64 && b <= 127);
    if (isPrivate) {
      error = 'Private, reserved or local IPs are not in Shodan InternetDB. Use a public IP.';
    } else {
      valid = true;
    }
  }
}

return [{ json: { valid, ip: valid ? ip : '', error, chat_id: chatId } }];

// Passive InternetDB result analysis. Deterministic severity: the AI never sets it.
const watchList = [135, 143, 443];
const src = $('Validate Input').first().json;
const res = $input.all().map(i => i.json)[0] || {};
const code = Number(res.statusCode);
const body = (res.body && typeof res.body === 'object' && !Array.isArray(res.body)) ? res.body : {};

// Treat everything from InternetDB as untrusted: keep only values with a safe shape
const ints = (v) => [...new Set((Array.isArray(v) ? v : []).map(Number).filter(n => Number.isInteger(n) && n > 0 && n < 65536))].sort((a, b) => a - b);
const strs = (v, re, max) => [...new Set((Array.isArray(v) ? v : []).map(x => String(x).trim()).filter(x => x.length > 0 && x.length <= 253 && re.test(x)))].slice(0, max);

const ports = ints(body.ports);
const hostnames = strs(body.hostnames, /^[A-Za-z0-9._-]+$/, 25);
const vulns = strs(body.vulns, /^CVE-\d{4}-\d{4,}$/i, 50).map(x => x.toUpperCase());
const tags = strs(body.tags, /^[A-Za-z0-9 ._-]+$/, 25);

let status = 'error';
if (code === 200 && (ports.length + hostnames.length + vulns.length) > 0) status = 'ok';
else if (code === 404 || code === 200) status = 'no_data';

const matched = ports.filter(p => watchList.includes(p));
const severity = matched.length > 0 ? 'HIGH' : 'NORMAL';

return [{
  json: {
    ip: src.ip,
    chat_id: src.chat_id,
    status,
    http_status: Number.isFinite(code) ? code : null,
    ports,
    hostnames,
    vulns,
    tags,
    matched_watchlist_ports: matched,
    severity,
    agent_input: { ip: src.ip, open_ports: ports, hostnames, known_cves: vulns, tags, matched_watchlist_ports: matched, deterministic_severity: severity }
  }
}];

const execId = $execution.id ? String($execution.id) : 'n/a';
const ist = $now.setZone('Asia/Kolkata').toFormat('dd-MM-yyyy HH:mm:ss') + ' IST';
const v = $('Validate Input').first().json;

let a = null;
if (v.valid) {
  try { a = $('Code in JavaScript').first().json; } catch (e) { a = null; }
}
const clean = (s, n) => String(s == null ? '' : s).replace(/[\r\n]+/g, ' ').replace(/\s+/g, ' ').trim().slice(0, n);

let header = '';
const lines = [];

if (!v.valid || !a) {
  header = '🔴 NGP-010 | exec #' + execId + ' | ' + ist + ' | INVALID INPUT | ' + clean(v.error || 'Could not process the request', 200);
  lines.push(header, '', 'Send: /ip <public IPv4 address>, for example /ip 1.1.1.1');
} else if (a.status !== 'ok') {
  const label = a.status === 'no_data' ? 'NO DATA' : 'LOOKUP ERROR';
  const why = a.status === 'no_data'
    ? 'InternetDB has no information for ' + a.ip + ' (this does not mean the host is safe)'
    : 'InternetDB lookup failed (HTTP ' + (a.http_status || 'no response') + '), please try again later';
  header = '🔴 NGP-010 | exec #' + execId + ' | ' + ist + ' | ' + label + ' | ' + why;
  lines.push(header, '', 'IP: ' + a.ip);
} else {
  let ai = null;
  try { ai = $('AI Agent').first().json.output; } catch (e) { ai = null; }

  const fallbackSteps = [
    'Close or firewall any internet-facing service that does not need to be public, and restrict the rest to trusted IP ranges.',
    'Keep exposed services patched, and check any listed CVEs against the real installed versions before drawing conclusions.',
    'Use strong authentication (keys or MFA), disable unused protocols, and monitor logs for the exposed ports.'
  ];
  let steps = fallbackSteps;
  if (ai && Array.isArray(ai.hardening_steps)) {
    const s = ai.hardening_steps.map(x => clean(x, 220)).filter(x => x.length > 0);
    if (s.length === 3) steps = s;
  }

  const matchedTxt = a.matched_watchlist_ports.length ? a.matched_watchlist_ports.join(', ') : 'none';
  let summary = a.severity === 'HIGH'
    ? 'Watch-list port(s) ' + matchedTxt + ' open on ' + a.ip + ', so severity is HIGH (an indicator to verify, not proof of a vulnerability).'
    : 'No watch-list ports open on ' + a.ip + ' (' + a.ports.length + ' open port(s) seen by InternetDB).';
  if (ai && typeof ai.summary === 'string' && ai.summary.trim()) {
    const cand = clean(ai.summary, 220);
    const downgrade = a.severity === 'HIGH' && /\b(low[- ]risk|no risk|not (a )?risk|safe|harmless|normal|benign|secure)\b/i.test(cand);
    const overclaim = /\b(is|are|was|were)\s+(definitely\s+)?(vulnerable|compromised|exploitable|hacked)\b/i.test(cand);
    if (!downgrade && !overclaim) summary = cand;
  }

  header = '🔴 NGP-010 | exec #' + execId + ' | ' + ist + ' | ' + a.severity + ' | ' + summary;
  const cves = a.vulns.length ? a.vulns.slice(0, 15).join(', ') + (a.vulns.length > 15 ? ' (+' + (a.vulns.length - 15) + ' more)' : '') : 'none listed';
  lines.push(
    header,
    '',
    'IP: ' + a.ip,
    'Open ports: ' + (a.ports.length ? a.ports.join(', ') : 'none'),
    'Matched watch-list ports: ' + matchedTxt,
    'Known CVEs (listed by InternetDB, not confirmed): ' + cves,
    'Hostnames: ' + (a.hostnames.length ? a.hostnames.slice(0, 10).join(', ') : 'none'),
    '',
    'Top 3 hardening steps:',
    '1. ' + steps[0],
    '2. ' + steps[1],
    '3. ' + steps[2],
    '',
    'Passive InternetDB data only. Open ports and listed CVEs do not prove a system is vulnerable.'
  );
}

return [{ json: { text: lines.join('\n') } }];

// Mask token-like strings and secrets in ALL text going to Telegram
let t = String($input.first().json.text || '');

const rules = [
  /\b\d{6,12}:[A-Za-z0-9_-]{30,}\b/g,                                  // Telegram bot tokens
  /\bsk-[A-Za-z0-9_-]{16,}\b/g,                                         // OpenAI-style keys
  /\b(?:gh[pousr]_[A-Za-z0-9]{20,}|github_pat_[A-Za-z0-9_]{20,})\b/g,   // GitHub tokens
  /\b(?:AKIA|ASIA)[A-Z0-9]{16}\b/g,                                     // AWS access key ids
  /\bxox[abprs]-[A-Za-z0-9-]{10,}\b/g,                                  // Slack tokens
  /\beyJ[A-Za-z0-9_-]{8,}\.[A-Za-z0-9_-]{8,}\.[A-Za-z0-9_-]{8,}\b/g,   // JWTs
  /\bBearer\s+[A-Za-z0-9._~+\/-]{12,}=*/gi,                            // Bearer tokens
  /-----BEGIN [A-Z ]*PRIVATE KEY-----[\s\S]*?(?:-----END [A-Z ]*PRIVATE KEY-----|$)/g,
  /\b(?:api[_-]?key|access[_-]?token|auth[_-]?token|token|secret|password|passwd|authorization)\b\s*[:=]\s*\S+/gi,
  /\b[A-Za-z0-9_-]{32,}\b/g                                             // any other long token-like string
];
for (const re of rules) t = t.replace(re, '[REDACTED]');

// The Telegram node sends HTML by default, so escape special characters
t = t.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

return [{ json: { text: t.slice(0, 4000) } }];
